/**
 * Validates EAN-8 or EAN-13 check digit.
 */
export function isValidEan(code) {
    if (!code) return false;
    const clean = String(code).trim();
    if (/^\d{8}$/.test(clean)) {
        const digits = clean.split("").map(Number);
        const checksum = digits.slice(0, 7).reduce((acc, d, i) => acc + d * (i % 2 === 0 ? 3 : 1), 0);
        const checkDigit = (10 - (checksum % 10)) % 10;
        return checkDigit === digits[7];
    }
    if (/^\d{13}$/.test(clean)) {
        const digits = clean.split("").map(Number);
        const checksum = digits.slice(0, 12).reduce((acc, d, i) => acc + d * (i % 2 === 0 ? 1 : 3), 0);
        const checkDigit = (10 - (checksum % 10)) % 10;
        return checkDigit === digits[12];
    }
    return false;
}

// Pre-index only verified valid barcodes for O(1) instantaneous lookups
const BARCODE_INDEX = new Map();
for (const p of NATIONAL_PRODUCTS) {
    if (p.barcode && isValidEan(p.barcode)) {
        BARCODE_INDEX.set(p.barcode.trim(), p);
    }
}

/**
 * Instant local lookup by exact or trimmed barcode.
 * Returns product object with suggested name, category, and price or null.
 */
export function findInNationalCatalog(barcode) {
    if (!barcode) return null;
    const clean = String(barcode).trim();
    if (!clean) return null;
    return BARCODE_INDEX.get(clean) || null;
}
